// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airdrop} from "../src/airdrop.sol";

contract InvMutTest is Test {
    airdrop c;
    function setUp() public { c = new airdrop(); }

    // fuzzed params: from address, boolean toggle for callee behaviour, uint v, single recipient address
    function testFuzz_property(address from, bool calleeShouldRevert, uint256 v, address tos) public {
        // keep tos non-zero to avoid trivial EOA zero-address weirdness in helper mapping
        vm.assume(tos != address(0));

        // deploy a helper that implements transferFrom(address,address,uint256)
        // and either reverts or returns true depending on calleeShouldRevert
        Recorder rec = new Recorder(calleeShouldRevert);

        // prepare tos array with exactly one recipient so external call happens once
        address[] memory recipients = new address[](1);
        recipients[0] = tos;

        // drive C.transfer and capture whether it reverted
        bool ok;
        try c.transfer(from, address(rec), recipients, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL RULE: reference C returns (does not revert) iff the callee's transferFrom call succeeded.
        // Our Recorder exposes whether its last call succeeded (it sets `succeeded` only when not reverting).
        // For the correct contract, ok == rec.succeeded(); the mutant inverts the check and will make this false for some inputs (when calleeShouldRevert flips).
        assertTrue(ok == rec.succeeded());
    }
}

// Helper that either reverts or returns true for transferFrom, and records whether it succeeded
contract Recorder {
    bool public shouldRevert;
    bool public succeeded;
    constructor(bool _shouldRevert) {
        shouldRevert = _shouldRevert;
    }
    // match the selector transferFrom(address,address,uint256)
    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        if (shouldRevert) {
            revert("forced revert");
        }
        // record that a successful call happened
        succeeded = true;
        return true;
    }
}
